// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 value, uint256 unlockTime, address actor) public {
        vm.assume(actor != address(0) && actor != address(this));
        uint256 preBal = address(c).balance;
        uint256 preAccBal = c.Acc(actor);
        vm.assume(value <= type(uint256).max - preAccBal);
        vm.deal(actor, value);
        vm.prank(actor);
        c.Put{value: value}(unlockTime);
        uint256 postAccBal = c.Acc(actor);
        assertTrue(address(c).balance >= postAccBal - preAccBal);
    }
}

