pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(uint256 amount1, uint256 amount2) public {
        // Keep amounts within uint256 limits; overflow requires amount2 to be large
        address actor = address(0xdead);
        vm.deal(actor, amount1 + amount2);
        vm.startPrank(actor);
        c.Put{value: amount1}(0);
        c.Put{value: amount2}(0);
        vm.stopPrank();

        (, uint256 recordedBalance) = c.Acc(actor);
        uint256 totalSent = amount1 + amount2;
        // The correct contract ensures recordedBalance equals totalSent because overflow sends would revert.
        // The mutant allows overflow, so recordedBalance != totalSent for some inputs.
        assertTrue(recordedBalance == totalSent);
    }
}

