        vm.assume(amount1 > 0);
        vm.assume(amount2 > 0);
        address actor = address(0x1000);
        vm.deal(actor, amount1 + amount2);

        // first deposit
        vm.prank(actor);
        c.Put{value: amount1}(0);
        ( , uint256 bal1) = c.Acc(actor);

        // second deposit
        vm.prank(actor);
        c.Put{value: amount2}(0);
        ( , uint256 bal2) = c.Acc(actor);

        // balance must never decrease
