pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 initialVal, uint256 putVal) public {
        // Bound to avoid overflow in reference (which reverts) but allow high values that wrap in buggy version
        vm.assume(initialVal <= type(uint256).max / 2);
        vm.assume(putVal > 0);
        vm.assume(putVal <= type(uint256).max / 2);
        // Ensure sum does not overflow: initialVal + putVal <= type(uint256).max (reference holds)
        vm.assume(initialVal <= type(uint256).max - putVal);

        address alice = address(0x1000);
        vm.deal(alice, initialVal + putVal);

        // First Put to set initial balance
        if (initialVal > 0) {
            vm.prank(alice);
            c.Put{value: initialVal}(uint256(block.timestamp + 100));
        }

        // Record contract balance before second Put
        uint256 balBefore = address(c).balance;

        // Second Put with putVal
        vm.prank(alice);
        c.Put{value: putVal}(uint256(block.timestamp + 100));

        uint256 balAfter = address(c).balance;

        // Contract balance must increase exactly by putVal
        assertTrue(balAfter == balBefore + putVal);
    }
}

