pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 value, uint256 unlockTime, uint8 preCalls) public {
        vm.assume(value > 0);
        vm.assume(preCalls <= 10);
        address addr = address(uint160(uint256(keccak256(abi.encode(value, unlockTime, preCalls)))));
        vm.assume(addr != address(this));
        for (uint i = 0; i < preCalls; i++) {
            vm.deal(addr, value);
            vm.prank(addr);
            c.Put{value: value}(block.timestamp);
        }
        (, uint256 balanceBefore) = c.Acc(addr);
        vm.deal(addr, value);
        vm.prank(addr);
        c.Put{value: value}(unlockTime);
        (, uint256 balanceAfter) = c.Acc(addr);
        assertTrue(balanceAfter - balanceBefore == value);
    }
}

