pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 _unlockTime, address sender) public {
        // Restrict unlockTime to a reasonable future timestamp to avoid overflow issues
        vm.assume(_unlockTime > block.timestamp && _unlockTime < type(uint256).max / 2);
        vm.assume(sender != address(0) && sender != address(c));
        // Ensure sender has some Ether to call Put
        vm.deal(sender, 1 ether);
        vm.prank(sender);
        c.Put{value: 1 ether}(_unlockTime);

        // The reference C should have set unlockTime to max(_unlockTime, block.timestamp)
        // The buggy version always sets unlockTime to block.timestamp.
        // Since we assumed _unlockTime > block.timestamp, the correct version must have unlockTime == _unlockTime,
        // while the buggy version has unlockTime == block.timestamp.
        // So the assertion is: unlockTime == _unlockTime.
        (uint unlockTime, uint balance) = c.Acc(sender);
        assertTrue(unlockTime == _unlockTime);
    }
}

