pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 _unlockTime, uint128 _am, address _sender) public {
        // 1. Admissible domain: sender must not be the test contract itself (to avoid interference with Log) and amount must be >0
        vm.assume(_sender != address(this) && _sender != address(0));
        vm.assume(_am > 0);
        // Bound unlockTime to reasonable future range
        uint256 futureTime = block.timestamp + 1 days;
        _unlockTime = bound(_unlockTime, futureTime, futureTime + 365 days);

        // 2. Setup: fund sender and call Put with the future unlockTime
        vm.deal(_sender, _am);
        vm.prank(_sender);
        c.Put{value: _am}(_unlockTime);

        // Record balance before collect
        uint256 balanceBefore = c.Acc(_sender).balance;

        // Try to Collect right now (which should fail for reference due to unlockTime in future)
        vm.prank(_sender);
        bool collectOk;
        try c.Collect(_am) { collectOk = true; } catch { collectOk = false; }

        uint256 balanceAfter = c.Acc(_sender).balance;

        // 3. Assertion: For reference contract, Collect must fail when block.timestamp <= unlockTime.
        // Since unlockTime is in the future, balanceAfter must equal balanceBefore (no collection happened).
        assertTrue(collectOk == false && balanceAfter == balanceBefore);
    }
}

