    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 collectAmt, uint8 adversarySeed) public {
        // adversarySeed decides whether we use a normal EOA or a reverter helper (unchecked return)
        address actor = address(uint160(uint256(keccak256(abi.encodePacked(adversarySeed, "actor")))));
        vm.assume(collectAmt >= 1 ether && collectAmt <= 100 ether);
        // actor deposits at least collectAmt + 1 ether
        uint256 depositAmt = collectAmt + 1 ether;
        vm.deal(actor, depositAmt);
        vm.prank(actor);
        c.Put{value: depositAmt}(0);

        // warp past unlock time
        vm.warp(block.timestamp + 1 days);

        // prepare adversary: half the runs use a reverter to test the unchecked low-level call
        address adversary = actor;
        if (adversarySeed % 2 == 0) {
            adversary = address(new Reverter());
        }

        // record balance before Collect
        uint256 contractBalanceBefore = address(c).balance;
        uint256 accBalanceBefore = c.Acc(adversary);
        // drive Collect through the adversary
        vm.prank(adversary);
        c.Collect(collectAmt);

        uint256 contractBalanceAfter = address(c).balance;
        uint256 accBalanceAfter = c.Acc(adversary);

        // Invariant: (accBalanceBefore + contractBalanceBefore) == (accBalanceAfter + contractBalanceAfter)
        // Reference maintains it; buggy transfers 0 ETH so sum decreases
        assertTrue(accBalanceBefore + contractBalanceBefore == accBalanceAfter + contractBalanceAfter);
    }
}

contract Reverter {
    fallback() external payable {
        revert("adversarial revert");
    }
}

