contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 putAmount, uint256 putUnlockTime, uint256 collectAmount, uint48 warpSeconds) public {
        // putAmount must be >= 1 ether to reach MinSum, and collectAmount must be <= putAmount.
        vm.assume(putAmount >= 1 ether);
        vm.assume(putAmount <= type(uint128).max);
        vm.assume(collectAmount > 0 && collectAmount <= putAmount);
        // warpSeconds bounds the unlock delay; keep it reasonable.
        vm.assume(warpSeconds > 0 && warpSeconds <= 365 days);

        address actor = address(uint160(uint256(keccak256(abi.encode("actor")))));
        vm.deal(actor, putAmount);

        // Record contract balance before Put.
        uint256 balBefore = address(c).balance;

        vm.prank(actor);
        c.Put{value: putAmount}(putUnlockTime);

        // Advance past unlock time.
        vm.warp(block.timestamp + warpSeconds + 1);

        // Record pre-Collect state.
        uint256 accBalanceBefore = c.Acc(actor).balance;
        uint256 contractBalBeforeCollect = address(c).balance;

        // Attempt Collect.
        bool ok;
        try c.Collect(collectAmount) { ok = true; } catch { ok = false; }

        if (ok) {
            uint256 contractBalAfterCollect = address(c).balance;
