import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 futureTime, uint256 putAmount, uint256 collectAmount, uint256 callerSeed) public {
        // Bound futureTime to be in the future but within reasonable limits
        vm.assume(futureTime > block.timestamp && futureTime < type(uint64).max);
        // Bound amounts to be > 0 and putAmount >= collectAmount >= MinSum to allow Collect to succeed
        vm.assume(putAmount > 0 && putAmount < type(uint128).max);
        vm.assume(collectAmount > 0 && collectAmount < type(uint128).max);
        vm.assume(putAmount >= collectAmount);
        vm.assume(putAmount >= c.MinSum());
        vm.assume(collectAmount >= c.MinSum());
        // Derive a unique caller from callerSeed to avoid collisions with setup address
        address caller = address(uint160(uint256(keccak256(abi.encodePacked(callerSeed)))));
        vm.assume(caller != address(this));
        vm.assume(caller != address(0));
        // Fund caller
        vm.deal(caller, putAmount * 2);
        // First Put
        vm.prank(caller);
        c.Put{value: putAmount}(futureTime);
        // Warp to futureTime + 1
        vm.warp(futureTime + 1);
        // Determine if Collect should succeed based on correct unlockTime logic (reference)
        // In reference: unlockTime = futureTime > block.timestamp at Put ? futureTime : block.timestamp
        // Since futureTime > original block.timestamp, unlockTime = futureTime.
        // After warp, block.timestamp = futureTime + 1 > unlockTime, so Collect should succeed.
        // In mutant: unlockTime remains 0, so after warp Collect also succeeds.
        // This doesn't differentiate because both succeed. We need the OPPOSITE: Collect BEFORE unlockTime.
        // Let's use a time warp that is AFTER the Put but BEFORE futureTime for reference to fail and mutant to succeed.
    }
}

